  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Direct absolute oral bioavailability of pethidine in healthy subjects is 0.52 (52%), exceeding the 20% threshold and supporting high bioavailability."
    },
    {
      "card_ids": ["C11"],
      "claim": "Direct absolute oral bioavailability of SAHA in fasting humans is 43%, exceeding the 20% threshold and supporting high bioavailability."
    },
    {
      "card_ids": ["C45"],
      "claim": "Direct absolute oral bioavailability of meptazinol in male volunteers is 8.69 ± 1.61%, below the 20% threshold and supporting low bioavailability."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C45"],
  "decision_summary": "Most direct human absolute oral bioavailability records (pethidine, SAHA, encainide, PEMA, FK788, tenidap, suprofen, R406, ziprasidone) exceed 20%, while meptazinol is consistently low; the balance of high-transfer, condition-matched evidence supports high bioavailability with moderate confidence.",
  "evidence_gaps": [
    "One high-transfer molecule (meptazinol) consistently shows low absolute oral bioavailability, conflicting with the positive evidence.",
    "Record C34 under Molecule 1 refers to morphine rather than pethidine; discounted as a provenance conflict.",
    "Some records use unspecified bioavailability types or altered populations, but the strongest condition-matched numeric records were prioritized."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C20", "C11"],
  "revision_action": "initial",
  "supportive_card_ids": ["C20", "C11"]
}

